-- Whether a snapshot is built is kept on its row rather than worked out
-- from its runs on every read: the run store sets it as the last context
-- builder ends.
--
-- Generated by drizzle-kit, then edited by hand in one place: the backfill
-- marks every snapshot already built as `snapshotBuilt` in core says (a
-- graphify run that succeeded, and every context builder ended), at the
-- time the last of those runs ended.
ALTER TABLE "repo_snapshot" ADD COLUMN "built_at" timestamp with time zone;--> statement-breakpoint
UPDATE "repo_snapshot" s
SET "built_at" = (
  SELECT max(a."finished_at")
  FROM "analysis_run" a
  WHERE a."snapshot_id" = s."id"
    AND a."tool" IN ('graphify', 'abstractions', 'data_model')
    AND a."status" IN ('succeeded', 'failed')
)
WHERE EXISTS (
    SELECT 1 FROM "analysis_run" a
    WHERE a."snapshot_id" = s."id" AND a."tool" = 'graphify' AND a."status" = 'succeeded'
  )
  AND (
    SELECT count(DISTINCT a."tool") FROM "analysis_run" a
    WHERE a."snapshot_id" = s."id"
      AND a."tool" IN ('graphify', 'abstractions', 'data_model')
      AND a."status" IN ('succeeded', 'failed')
  ) = 3;
